		const xs = points.map((point) => point.x)
		const ys = points.map((point) => point.y)
		const x = Math.min(...xs)
		const y = Math.min(...ys)
		const w = Math.max(...xs) - x
		const h = Math.max(...ys) - y
		return {
			type: 'create',
			shape: {
				id: `sketch-${id}`,
				type: 'path',
				x,
				y,
				w,
				h,
				color,
				brush,
				strokeWidth,
				points: points.map((point) => ({
					x: Math.min(w, Math.max(0, point.x - x)),
					y: Math.min(h, Math.max(0, point.y - y)),
				})),
			},
		}
	}),
]

